let current=null;
const COLORS={target:'#c3ef79',pattern:'#dfad72',match:'#88b7da',team:'#9aaa9b'};
export function stopMarketNetwork(){if(current){cancelAnimationFrame(current.frame);current.observer?.disconnect();current=null;}}
export function renderMarketNetwork(root,{bundle,result,esc,number,pct,date}){
 stopMarketNetwork();const network=result.marketNetwork,selection=result.training?.marketNetwork;
 if(!network?.graph?.nodes.length){root.innerHTML=`<section class="card"><h2>Pazar profili ağı</h2><p>${esc(network?.coverage?.reason??'Bu analizde doğrulanmış pazar ağı eğitim verisi bulunmuyor. Yeni maç verisi toplandığında geçmiş sonuçlar ve ağ eğitim verisi yeniden hazırlanır.')}</p></section>`;return;}
 const p=result.prediction,top=p?.topScores[0],comparison=selection?.comparison,before=comparison?.test.reference,after=comparison?.test.network;
 root.innerHTML=`<div class="section-heading"><h2>Pazarların arkasındaki bağlantılar</h2><span class="tag">${selection?.active?selection.experimental?'DENEYSEL PAZAR AĞI':'PAZAR AĞI ETKİN':'AĞ AÇIKLAYICI · MEVCUT MODEL'}</span></div><p class="section-desc">Maç → tekrar eden pazar durumu → benzer maçlar → takımlar. Düğümleri seçerek geçmiş sonuçları ve ortak profilleri açın. Ağın çizgileri yalnız başlama öncesi pazar profillerinden kurulur; geçmiş skorlar çizgiler kurulduktan sonra öğrenme sinyaline dönüştürülür.</p><div class="card mn-forecast"><div><span>Seçili modelin en olası skoru</span><strong>${top?top.home+' – '+top.away:'—'}</strong><b>${top?pct(top.probability):'—'}</b></div><p>${esc(selection?.reason??'Ağ mevcut modelle karşılaştırılır.')} Kesin skor garantisi yoktur. Ağ benzerliği, skor isabet yüzdesi değildir.</p><button class="text-button" data-view="overview">Skor projeksiyonunu aç ↗</button></div><div class="mini-stats"><div><b>${network.coverage.neighborCount}</b><span>BAĞLI GEÇMİŞ MAÇ</span></div><div><b>${number(network.coverage.effectiveSupport,1)}</b><span>ETKİN ÖRNEKLEM</span></div><div><b>${network.coverage.patternCount}</b><span>ORTAK PAZAR DURUMU</span></div><div><b>${result.training.featureNames?.length??0}</b><span>SEÇİLEN MODEL GİRDİSİ</span></div></div><section class="card mn-shell"><div class="mn-toolbar"><label>Düğüm ara<input class="filter-input" data-mn-search placeholder="Takım, maç veya pazar"></label><label>Görünüm<select data-mn-filter><option value="all">Tüm düğümler</option><option value="pattern">Pazarlar ve bağlı maçlar</option><option value="match">Maçlar ve takımlar</option><option value="selected">Seçilen düğümün komşuları</option></select></label><button class="button ghost" data-mn-zoom="in" aria-label="Pazar ağına yaklaş">+</button><button class="button ghost" data-mn-zoom="out" aria-label="Pazar ağından uzaklaş">−</button><button class="button ghost" data-mn-reset>Ortala</button></div><p class="inline-note">Sürükleyin, tekerlekle yakınlaşın veya listeden düğüm seçin. Görünüm filtreleri tahmin girdilerini değiştirmez. Tam etiket seçili düğümün ayrıntısında bulunur. Okunabilir görünümde en fazla 36 pazar düğümü çizilir; eğitimde tüm ortak durumlar kullanılır.</p><div class="mn-workspace"><div class="mn-stage"><svg role="img" aria-label="Maçlar, takımlar ve tekrar eden pazar profillerinin bağlantı ağı"><g data-mn-world></g></svg><div class="mn-legend">${Object.entries({target:'Hedef maç',pattern:'Pazar durumu',match:'Geçmiş maç',team:'Takım'}).map(([k,v])=>`<span><i style="background:${COLORS[k]}"></i>${v}</span>`).join('')}</div></div><aside class="mn-detail" aria-live="polite"></aside></div><details class="mn-list"><summary>Tüm düğümler · erişilebilir liste</summary><div data-mn-list></div></details></section><details class="card spaced" open><summary>Bağlı maçların gerçek sonuçları ve ağ ağırlıkları</summary><p class="inline-note">Maçlar hedef takım perspektifine ters çevrilebilir; kaynak bağlantısı gerçek ev/deplasman yönünü gösterir. Ağırlıklar toplamı 1’dir ve 8 adımlı sönümlü ağ yayılımından gelir; tek bir maçın skor olasılığı değildir.</p><div class="table-wrap"><table><thead><tr><th>GEÇMİŞ MAÇ / TARİH</th><th>SKOR</th><th>PROFİL BENZERLİĞİ</th><th>AĞ AĞIRLIĞI</th><th>ORTAK PAZAR</th></tr></thead><tbody>${[...network.neighbors].sort((a,b)=>b.weight-a.weight).map(n=>`<tr><td><button class="text-button" data-mn-match="${esc(n.id)}">${esc(n.homeTeam?.name??n.id)} – ${esc(n.awayTeam?.name??'')}</button><small>${date(n.date,true)}${n.reversed?' · hedefe göre yön değişti':''}</small></td><td>${n.homeScore} – ${n.awayScore}</td><td>${pct(n.similarity)}</td><td>${pct(n.weight,2)}</td><td>${n.sharedMarkets}/40</td></tr>`).join('')}</tbody></table></div></details>${before&&after?`<details class="card spaced"><summary>Aynı ${after.sampleSize} test maçında mevcut model ve pazar ağı</summary><div class="table-wrap"><table><thead><tr><th>İÇ TEST</th><th>MEVCUT MODEL</th><th>PAZAR AĞI</th></tr></thead><tbody><tr><td>Tam skor isabeti</td><td>${pct(before.exactScoreAccuracy)}</td><td>${pct(after.exactScoreAccuracy)}</td></tr><tr><td>1X2 isabeti</td><td>${pct(before.accuracy)}</td><td>${pct(after.accuracy)}</td></tr><tr><td>Skor log kaybı · düşük daha iyi</td><td>${number(before.pairedCountNll,3)}</td><td>${number(after.pairedCountNll,3)}</td></tr></tbody></table></div><p class="inline-note">${esc(selection.policy)} Doğrulama NLL kazancı: ${number(selection.validationNllGain,4)}. Bu, zaman sıralı iç testtir; bağımsız gelecek başarı kanıtı değildir.</p></details>`:''}<details class="card spaced"><summary>Ağ nasıl öğreniyor ve yeni sonuçlarla nasıl güncelleniyor?</summary><p>20 temel pazarın her iki takım için seri, sıklık ve veri kapsamı karşılaştırılır. En yakın 48 geçmiş maç, ortak pazar durumları üzerinden sekiz adımda bilgi paylaşır. Ev/deplasman yönü ve eski maçların ağırlığı dikkate alınır. Ağdaki geçmiş sonuçlar, 12 sayısal girdiyle karar ağaçlarına aktarılır; sabit bir skor veya zorunlu seri dönüşü eklenmez.</p><p>Yeni maç verisi toplandıktan sonra geçmiş sonuçlar ve ağ özellikleri yeniden hazırlanır. Eğitim dosyası ancak tüm adımlar başarılıysa tek seferde yayımlanır. Her analiz, hedef maçtan önce bilinen etiketlerle eğitim / doğrulama / test ayırır; hedef sonucun kendisi dışarıda kalır.</p><p>Geçmiş doğrulama/test maçları, ancak tamamlandıktan sonra daha sonraki maçların geçmişine girebilir. Model parametreleri test sonuçlarıyla seçilmez. Arşiv kapsamı, oyuncu senaryoları ve sayım modellerinin sınırları diğer ekranlarda ayrıca gösterilir.</p><p class="inline-note">Son ağ kanıtı: ${date(network.evidence.maxAvailableAt,true)} · ${network.evidence.matchIds.length} maç · hedef sonuç kullanılmadı.</p></details>`;
 const svg=root.querySelector('svg'),world=svg.querySelector('[data-mn-world]'),stage=root.querySelector('.mn-stage'),detail=root.querySelector('.mn-detail');
 const nodes=network.graph.nodes.map((n,i)=>({...n,index:i,x:0,y:0,vx:0,vy:0})),byId=new Map(nodes.map(n=>[n.id,n])),links=network.graph.links.map(l=>({...l,a:byId.get(l.source),b:byId.get(l.target)}));
 const state={frame:0,observer:null,selected:nodes.find(n=>n.type==='target'),pan:{x:0,y:0,k:1},width:600,height:560,search:'',filter:'all',tick:0};current=state;
 const radius=n=>n.type==='target'?17:n.type==='pattern'?6:n.type==='match'?8:5;
 const hash=s=>{let h=0;for(const ch of s)h=(h*31+ch.charCodeAt(0))>>>0;return h;};
 world.innerHTML=links.map(l=>`<line data-edge="${esc(l.source)}|${esc(l.target)}" stroke="${l.type==='profile-similarity'?'#88b7da':'#78916e'}" stroke-width="${l.type==='profile-similarity'?1.4:.8}"/>`).join('')+nodes.map(n=>`<g data-node="${n.index}" tabindex="0" role="button" aria-label="${esc(n.label)}"><circle r="${radius(n)}" fill="${COLORS[n.type]}"/><text text-anchor="middle" y="${radius(n)+18}" fill="${COLORS[n.type]}">${esc(n.label.length>24?n.label.slice(0,23)+'…':n.label)}</text><title>${esc(n.label)}</title></g>`).join('');
 const edgeElements=[...world.querySelectorAll('line')],nodeElements=[...world.querySelectorAll('[data-node]')];
 function transform(){world.setAttribute('transform',`translate(${state.pan.x} ${state.pan.y}) scale(${state.pan.k})`);}
 function paint(){const connected=new Set([state.selected?.id]);for(const l of links)if(l.source===state.selected?.id||l.target===state.selected?.id){connected.add(l.source);connected.add(l.target);}
  const visible=n=>!state.search||n.label.toLocaleLowerCase('tr-TR').includes(state.search);
  for(let i=0;i<nodes.length;i++){const n=nodes[i],el=nodeElements[i],focused=connected.has(n.id),typeOk=state.filter==='all'||state.filter==='selected'?state.filter==='all'||focused:state.filter==='pattern'?['target','pattern','match'].includes(n.type):['target','match','team'].includes(n.type);
   el.style.opacity=visible(n)&&typeOk?'1':'.08';el.setAttribute('transform',`translate(${n.x} ${n.y})`);el.querySelector('circle').setAttribute('stroke',n.id===state.selected?.id?'#fff':'none');
   el.querySelector('text').style.display=n.type==='target'||n.type==='team'&&n.detail?.side||n.id===state.selected?.id||state.pan.k>1.7||state.search&&visible(n)?'':'none';}
  for(let i=0;i<links.length;i++){const l=links[i],el=edgeElements[i];el.setAttribute('x1',l.a.x);el.setAttribute('y1',l.a.y);el.setAttribute('x2',l.b.x);el.setAttribute('y2',l.b.y);el.style.opacity=state.filter==='selected'?(connected.has(l.source)&&connected.has(l.target)?'.7':'.025'):'.24';}
 }
 function select(n){state.selected=n;const d=n.detail??{},neighbors=links.filter(l=>l.source===n.id||l.target===n.id).map(l=>byId.get(l.source===n.id?l.target:l.source));
  const unique=[...new Map(neighbors.map(v=>[v.id,v])).values()];
  detail.innerHTML=`<span class="tag">${{target:'HEDEF MAÇ',pattern:'PAZAR DURUMU',match:'GEÇMİŞ MAÇ',team:'TAKIM'}[n.type]}</span><h3>${esc(n.label)}</h3>${n.type==='match'?`<p><b>${d.homeScore} – ${d.awayScore}</b> · ${date(d.date,true)}</p><p>Profil benzerliği ${pct(d.similarity)}<br>Ağ ağırlığı ${pct(d.weight,2)}<br>${d.reversed?'Ev/deplasman yönü hedefe göre çevrildi.':''}</p><a href="${esc(d.url)}" target="_blank" rel="noreferrer">Kaynak maçı aç ↗</a>`:n.type==='pattern'?`<p>${d.side==='home'?'Ev':'Deplasman'} takımının maç öncesi pazar durumu.<br>Seri: ${esc(d.range)} maç.<br>Geçmiş sıklık aralığı: ${pct(d.frequencyRange[0],0)}–${pct(d.frequencyRange[1],0)}.<br>${d.matches} bağlı geçmiş maç.</p>`:n.type==='target'?`<p>Analiz kesimi ${date(bundle.analysisAt??bundle.target.date,true)}. Hedef maçın sonucu bu ağda kullanılmaz.</p>`:'<p>Bu takımın ağdaki maç ve pazar bağlantıları.</p>'}<h4>${unique.length} bağlantı</h4><div class="mn-neighbor-list">${unique.slice(0,30).map(v=>`<button data-mn-select="${v.index}">${esc(v.label)}</button>`).join('')}</div>`;
  detail.querySelectorAll('[data-mn-select]').forEach(b=>b.onclick=()=>select(nodes[Number(b.dataset.mnSelect)]));paint();}
 function resize(){const oldW=state.width,oldH=state.height;state.width=Math.max(300,stage.clientWidth);state.height=state.width<500?480:560;svg.setAttribute('viewBox',`0 0 ${state.width} ${state.height}`);svg.style.height=state.height+'px';
  for(const n of nodes){if(!state.tick){const angle=hash(n.id)%628/100,r=n.type==='target'?0:Math.min(state.width,state.height)*(n.type==='pattern'?.25:n.type==='match'?.36:.43);n.x=state.width/2+Math.cos(angle)*r;n.y=state.height/2+Math.sin(angle)*r;}else{n.x*=state.width/oldW;n.y*=state.height/oldH;}}paint();}
 function frame(){if(current!==state)return;state.tick++;const alpha=Math.max(.025,1-state.tick/180);
  for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=b.x-a.x,dy=b.y-a.y,r2=Math.max(16,dx*dx+dy*dy),length=Math.sqrt(r2),minimum=radius(a)+radius(b)+9,force=alpha*(12/r2+Math.max(0,minimum-length)*.04/length);a.vx-=dx*force;a.vy-=dy*force;b.vx+=dx*force;b.vy+=dy*force;}
  for(const l of links){const dx=l.b.x-l.a.x,dy=l.b.y-l.a.y,len=Math.max(1,Math.hypot(dx,dy)),ideal=l.type==='profile-similarity'?160:l.type==='current-pattern'?95:65,f=(len-ideal)/len*.018*alpha;l.a.vx+=dx*f;l.a.vy+=dy*f;l.b.vx-=dx*f;l.b.vy-=dy*f;}
  for(const n of nodes){if(n.type==='target'){n.x=state.width/2;n.y=state.height/2;n.vx=0;n.vy=0;continue;}if(n.drag)continue;n.vx=(n.vx+(state.width/2-n.x)*.003*alpha)*.78;n.vy=(n.vy+(state.height/2-n.y)*.003*alpha)*.78;n.x=Math.max(22,Math.min(state.width-22,n.x+Math.max(-8,Math.min(8,n.vx))));n.y=Math.max(24,Math.min(state.height-45,n.y+Math.max(-8,Math.min(8,n.vy))));}
  paint();if(state.tick<190)state.frame=requestAnimationFrame(frame);}
 const point=e=>{const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());};let dragging=null;
 svg.onpointerdown=e=>{const p=point(e),node=e.target.closest('[data-node]');dragging={x:p.x,y:p.y,moved:false,node:node?nodes[Number(node.dataset.node)]:null};if(dragging.node)dragging.node.drag=true;svg.setPointerCapture(e.pointerId);};
 svg.onpointermove=e=>{if(!dragging)return;const p=point(e),dx=p.x-dragging.x,dy=p.y-dragging.y;dragging.moved||=Math.hypot(dx,dy)>2;if(dragging.node){dragging.node.x+=dx/state.pan.k;dragging.node.y+=dy/state.pan.k;}else{state.pan.x+=dx;state.pan.y+=dy;transform();}dragging.x=p.x;dragging.y=p.y;paint();};
 svg.onpointerup=()=>{if(dragging?.node){dragging.node.drag=false;if(!dragging.moved)select(dragging.node);}dragging=null;};svg.onpointercancel=svg.onpointerup;
 const zoom=(factor,p={x:state.width/2,y:state.height/2})=>{const old=state.pan.k,next=Math.max(.35,Math.min(3.5,old*factor));state.pan.x=p.x-(p.x-state.pan.x)*next/old;state.pan.y=p.y-(p.y-state.pan.y)*next/old;state.pan.k=next;transform();};
 svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12,point(e));},{passive:false});
 for(const el of nodeElements)el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(nodes[Number(el.dataset.node)]);}};
 root.querySelector('[data-mn-search]').oninput=e=>{state.search=e.target.value.trim().toLocaleLowerCase('tr-TR');paint();};root.querySelector('[data-mn-filter]').onchange=e=>{state.filter=e.target.value;paint();};
 root.querySelectorAll('[data-mn-zoom]').forEach(b=>b.onclick=()=>zoom(b.dataset.mnZoom==='in'?1.25:.8));root.querySelector('[data-mn-reset]').onclick=()=>{state.pan={x:0,y:0,k:1};transform();paint();};
 root.querySelector('[data-mn-list]').innerHTML=nodes.map(n=>`<button class="button ghost" data-mn-item="${n.index}">${esc(n.label)}</button>`).join('');root.querySelectorAll('[data-mn-item]').forEach(b=>b.onclick=()=>select(nodes[Number(b.dataset.mnItem)]));
 root.querySelectorAll('[data-mn-match]').forEach(b=>b.onclick=()=>{const n=byId.get('match:'+b.dataset.mnMatch);if(n){select(n);root.querySelector('.mn-shell').scrollIntoView({behavior:'smooth',block:'start'});}});
 state.observer=new ResizeObserver(resize);state.observer.observe(stage);resize();select(state.selected);state.frame=requestAnimationFrame(frame);
}
